	public class UseFlameSlash : ProjectileAttackState
	{
		public new static string staticID = "UseFlameSlash";

		private float flyTime = 0.35f;

		private FlameSlash currentFS;

		private Vector2 spawnPosition;

		private Vector2 spawnOffset;

		private Vector2 perpendVec;

		private int ultStopwatchID;

		private int ultCounter;

		private bool ultStarted;

		public override string OnEnterAnimStr => (!IsEmpowered) ? parent.NextHandAnimStr : parent.PBAoEAnimStr;

		public UseFlameSlash(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			SetAnimTimes(0.25f, 0.2f, 0.3f, 0.6f, 0.75f);
			InitChargeSkillSettings(2, 0.125f, skillData, this);
		}

		public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			base.SetEmpowered(givenStatus, givenMod);
			flyTime = ((!IsEmpowered) ? 0.35f : 0.45f);
		}

		public override void OnEnter()
		{
			if (isUltimate)
			{
				SetSkillLevel(2);
				cooldownRef.chargeCount = 0;
				ultStarted = false;
			}
			else
			{
				SetSkillLevel(1);
			}
			base.OnEnter();
			spawnOffset = inputVector * 0.5f;
		}

		public override void ExecuteSkill()
		{
			if (isUltimate)
			{
				if (!ultStarted)
				{
					ultStarted = true;
					ultStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.1f, 6);
					ultCounter = 0;
				}
				switch (ChaosStopwatch.CheckInterval(ultStopwatchID))
				{
				case StopwatchState.Ready:
					spawnPosition = (Vector2)parent.attackOriginTrans.position + spawnOffset;
					if (ultCounter == 0)
					{
						perpendVec = Globals.GetPerpendicular(inputVector) * 0.5f;
						CreateFlameSlash(spawnPosition + perpendVec, inputVector, flipX: true);
						CreateFlameSlash(spawnPosition - perpendVec, inputVector);
					}
					else
					{
						for (int i = -ultCounter; i <= ultCounter; i++)
						{
							CreateFlameSlash(spawnPosition, Globals.GetRotatedCircleVector(24, i, inputVector));
						}
					}
					ultCounter++;
					parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animExecTime);
					break;
				case StopwatchState.Done:
					base.ExecuteSkill();
					parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, animExecTime);
					break;
				}
			}
			else
			{
				base.ExecuteSkill();
				spawnPosition = (Vector2)parent.attackOriginTrans.position + spawnOffset;
				if (IsEmpowered)
				{
					perpendVec = Globals.GetPerpendicular(inputVector) * 0.5f;
					CreateFlameSlash(spawnPosition + perpendVec, inputVector, flipX: true);
					CreateFlameSlash(spawnPosition - perpendVec, inputVector);
				}
				else
				{
					CreateFlameSlash(spawnPosition, inputVector, !parent.forehandAnimPlayed);
				}
			}
		}

		private void CreateFlameSlash(Vector2 givenPosition, Vector2 givenVector, bool flipX = false)
		{
			CameraController.ShakeCamera(0.4f);
			currentFS = (FlameSlash)CreateProjectile(FlameSlash.Prefab, givenPosition, Globals.GetRotationQuaternion(inputVector));
			currentFS.flyTime = flyTime;
			if (flipX)
			{
				currentFS.transform.localScale = new Vector3(-1f, 1f, 1f);
			}
			FireProjectile(currentFS, givenVector, setKnockbackVector: true, 0f, 0f, string.Empty);
		}
	}

		public virtual void SetAnimTimes(float newStart = 0f, float newHold = 0.2f, float newExecute = 0.3f, float newCancel = 0.6f, float newRun = 0.8f, float newExit = 1f)
		{
			animStartTime = newStart;
			animHoldTime = newHold;
			animExecTime = newExecute;
			cancelThreshold = newCancel;
			runThreshold = newRun;
			exitThreshold = newExit;
		}

		public void InitChargeSkillSettings(int maxCharges, float delayBetweenCharges, StatData statData, SkillState skillState)
		{
			isChargeSkill = true;
			cooldownRef.isChargeSkill = true;
			cooldownRef.chargeCount = maxCharges;
			cooldownRef.MaxChargeCount = maxCharges;
			cooldownRef.chargeDelayTime = delayBetweenCharges;
			cooldownRef.statData = statData;
			cooldownRef.skillState = skillState;
			cooldownRef.remainingTimeStopwatchID = -1;
			cooldownRef.delayStopwatchID = -1;
		}

		public virtual void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			empoweredStat.Modify(givenMod, givenStatus);
			if (parent.skillEmpowerEventHandlers != null)
			{
				parent.skillEmpowerEventHandlers(this);
			}
		}

		public virtual bool IsReady()
		{
			if ((isMovementSkill && !parent.MovementEnabled) || (isUltimate && !IsOverdriveReady()) || (!isUltimate && !cooldownRef.Ready))
			{
				return false;
			}
			if (allowSelfTransition && !allowRepeating && repeatLock)
			{
				return false;
			}
			return true;
		}

		public virtual bool IsOverdriveReady()
		{
			return true;
		}

		public bool Transition()
		{
			if (!IsReady() || (!allowSelfTransition && fsm.currentStateName == skillID))
			{
				return false;
			}
			fsm.ChangeState(skillID, allowSelfTransition: true);
			return true;
		}

		public int SetSkillSlot()
		{
			for (int i = 0; i < parent.assignedSkills.Length; i++)
			{
				if (parent.assignedSkills[i] != null && parent.assignedSkills[i].skillID == skillID)
				{
					skillSlot = i;
					return skillSlot;
				}
			}
			skillSlot = -1;
			return skillSlot;
		}

		public void SetRepeatLock(bool setLock = true)
		{
			repeatLock = setLock;
		}

		public void UpdateRepeatLock(string buttonName = "")
		{
			if (skillSlot != -1)
			{
				if (buttonName == string.Empty)
				{
					buttonName = "Skill" + skillSlot;
				}
				if (parent.inputDevice.GetButtonUp(buttonName))
				{
					SetRepeatLock(setLock: false);
				}
			}
		}

		public virtual void StartCooldownTimer(float overrideValue = -1f, bool expendCharge = true)
		{
			if (useSmartCD)
			{
				if (cdStarted)
				{
					return;
				}
				cdStarted = true;
			}
			if ((skillData.GetValue<float>("cooldown") == 0f && overrideValue == -1f) || parent == null || parent.gameObject == null || !parent.gameObject.activeSelf)
			{
				return;
			}
			if (isChargeSkill)
			{
				if (expendCharge && cooldownRef.chargeCount > 0)
				{
					cooldownRef.chargeCount = Mathf.Max(0, cooldownRef.chargeCount - ((!(overrideValue > 0f)) ? 1 : ((int)overrideValue)));
				}
				parent.StartCoroutine(parent.cooldownManager.StartChargeCounter(skillID));
			}
			else
			{
				parent.cooldownManager.StartCooldownTimer(skillID, overrideValue);
		public virtual void ExecuteSkill()
		{
			skillExecuted = true;
			AnnounceSkillExecuteEvent();
		}

		public virtual void AnnounceSkillExecuteEvent()
		{
			if (parent.skillExecEventHandlers != null)
			{
				parent.skillExecEventHandlers(this);
			}
		}

		public virtual void ConcludeSkill()
		{
			ExitToSkillOrRunOrIdle();
		}

		public override void OnExit()
		{
			if (allowSelfTransition && !allowRepeating && GetType() != fsm.nextState.GetType())
			{
				SetRepeatLock(setLock: false);
			}
			if (!disableStartCooldown && !startCooldownOnEnter)
			{
				StartCooldownTimer();
			}
			if (parent.skillExitEventHandlers != null)
			{
				parent.skillExitEventHandlers(this);
			}
		}

		public void SetSkillLevel(int skillLevel)
		{
			currentLevel = skillLevel;
			skillData.currentLevel = skillLevel;
		}

		public Vector2 GetInputVector(bool faceInputVector = true, bool useAimVector = true, bool ignoreZero = true)
		{
			return parent.GetInputVector(faceInputVector, useAimVector, ignoreZero);
		}

		public bool CancelToDash(bool enableButtonHeld = false)
		{
			cancelToDashSkill = parent.GetDashSkill();
			return cancelToDashSkill != null && parent.TransitionToSkill(cancelToDashSkill.SetSkillSlot(), enableButtonHeld);
		}

		public bool CancelToSkills(bool overrideThresholdReq = false)
using UnityEngine;

public class FlameSlash : Projectile
{
	private static GameObject prefab;

	public Transform partSysTrans;

	public ParticleSystem[] firePartSystems;

	private bool partSysReset;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/FlameSlash.prefab"));

	public override void Start()
	{
		base.Start();
		string audioID = "VacuumExplosion";
		Vector2? soundOrigin = transform.position;
		float overridePitch = Random.Range(0.85f, 0.95f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
	}

	public override void ResetProjectile()
	{
		if (!partSysReset)
		{
			partSysReset = true;
			for (int i = 0; i < firePartSystems.Length; i++)
			{
				if (firePartSystems[i] != null)
				{
					firePartSystems[i].Stop();
				}
			}
			partSysTrans.SetParent(null);
			partSysTrans.gameObject.AddComponent<Rigidbody2D>().AddForce(moveVector * moveSpeed * 35f);
			Object.Destroy(partSysTrans.gameObject, 0.75f);
			SoundManager.PlayAudioWithDistance("FireBlastODEnd", transform.position);
		}
		base.ResetProjectile();
	}
}

