	public class UseFlameBuster : ProjectileAttackState
	{
		public new static string staticID = "UseFlameBuster";

		private FlameBuster currentFB;

		private GameObject primaryAtkObj;

		private Vector2 atkPosition;

		private Vector2 checkAimVec;

		private bool primaryFired;

		private NumVarStatMod speedMod;

		private ChaosQuickStopwatch holdStopwatch = new ChaosQuickStopwatch();

		public override string OnEnterAnimStr => parent.ForehandAnimStr;

		public UseFlameBuster(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			startCooldownOnEnter = false;
			useSmartCD = true;
			SetAnimVars();
			speedMod = new NumVarStatMod(staticID, 12f, 10, VarStatModType.OverrideWithMods);
		}

		private void SetAnimVars(bool isPrimary = true)
		{
			if (isPrimary)
			{
				SetAnimTimes(0.1f, 0.2f, 0.3f, 0.4f, 0.6f);
			}
			else
			{
				SetAnimTimes(0.1f, 0.2f, 0.25f);
			}
		}

		public override void OnEnter()
		{
			SetAnimVars();
			base.OnEnter();
			primaryFired = false;
			parent.movement.moveSpeedStat.AddMod(speedMod);
			holdStopwatch.IsRunning = true;
		}

		public override void Update()
		{
			if (!skillExecuted || !CancelToSkills())
			{
				base.Update();
			}
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			ShootBuster(!primaryFired);
			CameraController.ShakeCamera(0.25f);
		}

		public override void ConcludeSkill()
		{
			if (primaryFired)
			{
				ExitToSkillOrRunOrIdle();
			}
			else if (parent.anim.AnimPlayed(runThreshold) && (!parent.inputDevice.GetButton("Skill" + skillSlot) || !holdStopwatch.IsRunning))
			{
				primaryFired = true;
				skillExecuted = false;
				checkAimVec = GetInputVector(faceInputVector: false, useAimVector: true, ignoreZero: false);
				if (checkAimVec != Vector2.zero)
				{
					inputVector = GetInputVector(faceInputVector: true, useAimVector: true, ignoreZero: false);
				}
				parent.movement.moveVector = inputVector;
				parent.movement.MoveToMoveVector();
				SetAnimVars(isPrimary: false);
				parent.anim.PlayDirectional(parent.KickAnimStr, -1, animStartTime);
				CameraController.ShakeCamera(0.25f);
				StartCooldownTimer();
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.movement.moveSpeedStat.RemoveMod(speedMod);
		}

		private void ShootBuster(bool isPrimary = true)
		{
			SetSkillLevel(isPrimary ? 1 : 2);
			atkPosition = parent.attackOriginTrans.position;
			currentFB = (FlameBuster)CreateProjectile(FlameBuster.Prefab, atkPosition);
			currentFB.isEmpowered = IsEmpowered;
			currentFB.isPrimary = isPrimary;
			if (isPrimary)
			{
				primaryAtkObj = currentFB.attackBox.gameObject;
				currentFB.transform.position += (Vector3)(inputVector * 0.5f);
				FireBurst poolItem = PoolManager.GetPoolItem<FireBurst>();
				int? particleCount = 10;
				Vector3? position = atkPosition - inputVector * 0.75f;
				Vector3? localEulerAngles = Globals.GetRotationVector(inputVector);
				poolItem.EmitSingle(particleCount, position, null, localEulerAngles);
			}
			else
			{
				currentFB.primaryAtkObj = primaryAtkObj;
				FireBurst poolItem2 = PoolManager.GetPoolItem<FireBurst>();
				int? particleCount = 5;
				Vector3? localEulerAngles = atkPosition;
				Vector3? position = Globals.GetRotationVector(inputVector);
				poolItem2.EmitSingle(particleCount, localEulerAngles, null, position);
			}
			FireProjectile(currentFB, inputVector, setKnockbackVector: true, 0f, 0f, string.Empty);
		}
	}

