	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/FlameBuster.prefab"));

	public override void Awake()
	{
		base.Awake();
		primaryPartSys = transform.Find("PrimaryEmitter").GetComponent<ParticleSystem>();
		secondaryPartSys = transform.Find("SecondaryEmitter").GetComponent<ParticleSystem>();
	}

	public override void Start()
	{
		if (isPrimary)
		{
			flyTime = 1.5f;
			moveSpeed = 10f;
			anim.Play("Primary", -1, 0f);
			primaryPartSys.Play();
			rotation = true;
			SoundManager.PlayAudioWithDistance("IgnitionOrbForm", transform.position);
			string audioID = "IgnitionOrbLoop";
			Transform originTrans = transform;
			SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
		}
		else
		{
			flyTime = 0.4f;
			moveSpeed = 40f;
			anim.Play("Secondary", -1, Random.value);
			secondaryPartSys.Play();
			if (isEmpowered)
			{
				transform.localScale *= 1.5f;
			}
			else if (!isDoubleBuster)
			{
				transform.localScale *= 1.25f;
			}
			SoundManager.PlayAudioWithDistance("FireArcStart", transform.position);
		}
		base.Start();
	}

	public override void FixedUpdate()
	{
		if (isPrimary && !lerpComplete)
		{
			lerpValue = lerpStopwatch.TimePercentage;
			moveSpeed = Mathf.Lerp(16f, 10f, lerpValue);
			if (lerpValue >= 1f)
			{
				lerpComplete = true;
			}
		}
		base.FixedUpdate();
	}

	public override void ResetProjectile()
	{
		if (resetQueued)
		{
			return;
		}
		resetQueued = true;
		updateVelocity = false;
		rigidbody2D.velocity = Vector2.zero;
		primaryPartSys.Stop();
		secondaryPartSys.Stop();
		anim.Play("Idle", -1, 0f);
		projectileLight.SetActive(value: false);
		Object.Destroy(gameObject, 1f);
		if (!spawnExplosion)
		{
			return;
		}
		if (isPrimary)
		{
			if (isDoubleBuster)
			{
				FireExplosion.SpawnExplosion(transform.position, 1f, 1f, 40, 50);
			}
			else
			{
				FireExplosion.SpawnExplosion(transform.position, 1f, 1f, 30, 45);
			}
		}
		else
		{
			FireExplosion.SpawnExplosion(transform.position, 0.25f, 0.5f);
		}
	}

	public override void HandleProjectileCollision(Collider2D otherCol)
	{
		if (!isPrimary && !isDoubleBuster && otherCol != null)
		{
			otherFB = otherCol.GetComponentInParent<FlameBuster>();
			if (otherFB != null && !otherFB.isDoubleBuster && otherFB.isPrimary)
			{
				spawnExplosion = false;
				otherFB.moveVector = moveVector;
				otherFB.DoubleBuster();
				DoubleBuster();
			}
		}
		base.HandleProjectileCollision(otherCol);
	}

	public void DoubleBuster()
	{
		isDoubleBuster = true;
		if (isPrimary)
		{
			spawnPosition = (Vector2)transform.position - moveVector * 0.5f;
			PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter").Emit(10, spawnPosition, SmokeEmitter.SmokeSecondaryOverride, null, 0.15f);
			CameraController.ShakeCamera(0.5f);
			SoundManager.PlayAudioWithDistance("VacuumExplosion", spawnPosition);
			attackBox.gameObject.SetActive(value: false);
			attackBox.ChangeAttackInfoLevel(3);
			calcCount = busterCount + (isEmpowered ? 2 : 0);
			halfCount = (int)((float)calcCount * 0.5f);
			for (int i = 0; i < calcCount; i++)
			{
				spawnedVector = Globals.GetRotatedCircleVector(busterSpreadValue, i - halfCount, moveVector);
				spawnedFB = Globals.ChaosInst<FlameBuster>(Prefab, transform.parent, spawnPosition + spawnedVector * 0.5f, Globals.GetRotationQuaternion(spawnedVector));
				spawnedFB.parentObject = parentObject;
				spawnedFB.parentEntity = parentEntity;
				spawnedFB.attackBox.SetAttackInfo(attackBox.atkInfo, 3);
				spawnedFB.attackBox.knockbackOverwriteVector = spawnedVector;
				spawnedFB.moveVector = spawnedVector;
				spawnedFB.isPrimary = false;
				spawnedFB.isDoubleBuster = true;
			}
		}
		ResetProjectile();
	}
