using UnityEngine;

public class VacuumFlame : Projectile
{
	private static GameObject prefab;

	public ParticleSystem sunEffect;

	public ParticleSystem flameRing0;

	public ParticleSystem flameRing1;

	public ParticleSystem implosionEffect;

	public GameObject orbitSpriteObj;

	private static Vector3 OrbitRotVec = new Vector3(0f, 0f, 720f);

	private VacuumFlameSmall[] vacuumSmallArray = new VacuumFlameSmall[6];

	private VacuumFlameSmall curVacuumSmall;

	private const int VortexCount = 6;

	protected VortexParticleEffect[] vortEffects = new VortexParticleEffect[6];

	protected Vector2[] vortAngles = new Vector2[6];

	private CircleCollider2D[] circCols;

	private CircleCollider2D attackCollider;

	[HideInInspector]
	public int baseDamage;

	private bool releaseVarsSet;

	[HideInInspector]
	public bool released;

	[HideInInspector]
	public int maxCharge = 10;

	[HideInInspector]
	public int currentCharge;

	[HideInInspector]
	public bool isUltimate;

	private float atkRadius = 3f;

	private float chargeProgress;

	[HideInInspector]
	public bool fullyCharged;

	private bool targetHit;

	private int hitStopwatchID;

	private float hitDelay = 0.125f;

	private bool destroyQueued;

	public ParticleSystem warmEmitter;

	private ParticleSystem.EmissionModule warmEmitMod;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/VacuumFlame.prefab"));

	private float LerpValue => (float)currentCharge / (float)maxCharge;

	public override void Awake()
	{
		base.Awake();
		for (int i = 0; i < 6; i++)
		{
			ref Vector2 reference = ref vortAngles[i];
			reference = Vector2.one * i * 120f;
		}
		circCols = GetComponentsInChildren<CircleCollider2D>();
		attackCollider = attackBox.GetComponent<CircleCollider2D>();
		EnableColliders(status: false);
		warmEmitMod = warmEmitter.emission;
	}

	public override void Start()
	{
		if (isUltimate)
		{
			orbitSpriteObj.SetActive(value: true);
			((CircleCollider2D)attackBox.collider).radius = 1.25f;
			atkRadius = 4.5f;
		}
		else
		{
			atkRadius = 3f;
		}
		base.Start();
		baseDamage = Mathf.Max(0, calculatedDamage);
		Attack attack = attackBox;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
		Attack attack2 = attackBox;
		attack2.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack2.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
	}

	public override void Update()
	{
		if (!releaseVarsSet)
		{
			chargeProgress = LerpValue;
			fullyCharged = chargeProgress == 1f;
			HandleChargeProgress(chargeProgress);
			if (!released)
			{
				return;
			}
			releaseVarsSet = true;
			SetReleaseVars();
			moveSpeed *= chargeProgress;
		}
		if (!targetHit)
		{
			base.Update();
		}
		if (destroyQueued || !isUltimate || !targetHit || !(transform != null) || !(rigidbody2D != null))
		{
			return;
		}
		for (int i = 0; i < vacuumSmallArray.Length; i++)
		{
			if (!(vacuumSmallArray[i] == null) && !(vacuumSmallArray[i].movement == null) && vacuumSmallArray[i].movement.moveSpeedStat != null && !(vacuumSmallArray[i].movement.rigidbody2D == null))
			{
				vacuumSmallArray[i].movement.OrbitTarget(transform.position);
			}
		}
	}

	public override void HandleRotation()
	{
		base.HandleRotation();
		if (isUltimate && !targetHit)
		{
			orbitSpriteObj.transform.Rotate(OrbitRotVec * Time.fixedDeltaTime);
		}
	}

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (!targetHit || destroyQueued)
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
		{
		case StopwatchState.Ready:
			currentCharge--;
			SoundManager.PlayWithDistAndSPR("FireWallStart", transform.position);
			if (currentCharge == 0)
			{
				if (fullyCharged)
				{
					attackBox.ChangeAttackInfoLevel((!isUltimate) ? 3 : 4);
					if (isUltimate)
					{
						FireExplosion.SpawnExplosion(transform.position, 2.5f, 1f, 150, 150);
					}
					else
					{
						FireExplosion.SpawnExplosion(transform.position, 2f, 1f, 100, 100);
					}
					SoundManager.PlayAudioWithDistance("CombustionWaveEnd", transform.position);
				}
				else
				{
					FireExplosion.SpawnExplosion(transform.position, 2f, 1f, 20, 20);
				}
			}
			attackCollider.enabled = true;
			break;
		case StopwatchState.Running:
			attackCollider.enabled = false;
			break;
		case StopwatchState.Done:
			ResetProjectile();
			break;
		}
	}

	public override void OnProjectileCollision(Collider2D other, Projectile otherProjectile, bool doCalculations = true)
	{
		if (doCalculations)
		{
			int num = calculatedDamage - otherProjectile.calculatedDamage;
			otherProjectile.calculatedDamage -= calculatedDamage;
			calculatedDamage = num;
			otherProjectile.OnProjectileCollision(other, this, doCalculations: false);
		}
		if (calculatedDamage > 10)
		{
			currentCharge = Mathf.CeilToInt(calculatedDamage / baseDamage);
			otherProjectile.calculatedDamage = 0;
		}
		else
		{
			currentCharge = 0;
			calculatedDamage = 0;
			HandleCollision(other);
		}
		collidedProjectiles.Add(otherProjectile);
	}

	public override void ResetProjectile()
	{
		if (!targetHit && released)
		{
			OnTargetHit(null);
		}
		else
		{
			if (destroyQueued)
			{
				return;
			}
			destroyQueued = true;
			warmEmitter.Stop();
			projectileSpriteRenderer.enabled = false;
			projectileLight.SetActive(value: false);
			Attack attack = attackBox;
			attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
			for (int i = 0; i < 6; i++)
			{
				if (vortEffects[i] != null)
				{
					vortEffects[i].Stop();
				}
			}
			if (isUltimate)
			{
				sunEffect.gameObject.SetActive(value: false);
				for (int j = 0; j < vacuumSmallArray.Length; j++)
				{
					if (!(vacuumSmallArray[j] == null))
					{
						vacuumSmallArray[j].CleanUp();
					}
				}
				sunEffect.Stop();
				flameRing0.Stop();
				flameRing1.Stop();
				flameRing0.Clear();
				flameRing1.Clear();
				implosionEffect.gameObject.SetActive(value: true);
			}
			ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter");
			poolItem.Emit(4, transform.TransformPoint(Vector3.up * 1.2f + Vector3.left), SmokeEmitter.SmokeMedOverride);
			poolItem.Emit(4, transform.TransformPoint(Vector3.up * 1.2f + Vector3.right), SmokeEmitter.SmokeMedOverride);
			poolItem.Emit(4, transform.TransformPoint(Vector3.down * 1.2f + Vector3.right), SmokeEmitter.SmokeMedOverride);
			poolItem.Emit(4, transform.TransformPoint(Vector3.down * 1.2f + Vector3.left), SmokeEmitter.SmokeMedOverride);
			poolItem.Emit(4, transform.position, SmokeEmitter.SmokeMedOverride);
			attackCollider.enabled = false;
			moveSpeed = 0f;
			UnityEngine.Object.Destroy(gameObject, 1f);
		}
	}

	public void EnableColliders(bool status = true)
	{
		CircleCollider2D[] array = circCols;
		foreach (CircleCollider2D circleCollider2D in array)
		{
			circleCollider2D.enabled = status;
		}
	}

	private void HandleChargeProgress(float givenValue)
	{
		warmEmitMod.rateOverTime = (int)Mathf.Lerp(0f, 80f, givenValue);
	}

	private void SetReleaseVars()
	{
		EnableColliders();
		calculatedDamage = baseDamage * currentCharge;
	}

	private void OnTargetHit(Collider2D col)
	{
		if (targetHit)
		{
			return;
		}
		targetHit = true;
		moveSpeed = 0f;
		wallCollider.enabled = false;
		attackCollider.enabled = false;
		hitStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, hitDelay, currentCharge);
		attackBox.ChangeAttackInfoLevel(2);
		(attackBox.collider as CircleCollider2D).radius = 2.5f;
		ignoreProjectileCollisions = true;
		orbitSpriteObj.SetActive(value: false);
		if (isUltimate)
		{
			((CircleCollider2D)attackBox.collider).radius = atkRadius;
			for (int i = 0; i < vacuumSmallArray.Length; i++)
			{
				curVacuumSmall = Globals.ChaosInst<VacuumFlameSmall>(VacuumFlameSmall.Prefab, null, transform.position);
				vacuumSmallArray[i] = curVacuumSmall;
				if (i <= 2)
				{
					curVacuumSmall.movement.orbitRadius = 3f;
					curVacuumSmall.movement.orbitSpeed = 6f;
					curVacuumSmall.movement.InitOrbitAngle(Globals.GetCirclePositionVector(3, i));
				}
				else
				{
					curVacuumSmall.movement.orbitRadius = 4f;
					curVacuumSmall.movement.orbitSpeed = 2f;
					curVacuumSmall.movement.transform.localScale = Globals.ScaleVec0p75;
					curVacuumSmall.movement.InitOrbitAngle(Globals.GetRotatedCircleVector(3, vacuumSmallArray.Length - 1 - i, Vector3.down));
				}
			}
			projectileSpriteRenderer.transform.localScale = Vector3.one * 1.75f;
			FireExplosion.SpawnExplosion(transform.position, 2.5f, 1f, 150, 150);
			flameRing0.gameObject.SetActive(value: true);
			flameRing1.gameObject.SetActive(value: true);
		}
		else
		{
			for (int j = 0; j < 6; j++)
			{
				vortEffects[j] = PoolManager.GetPoolItem<VortexParticleEffect>("FireVortexEffect");
				VortexParticleEffect vortexParticleEffect = vortEffects[j];
				vortexParticleEffect.startAngleRange = vortAngles[j];
				vortexParticleEffect.startRadius = atkRadius;
				vortexParticleEffect.rotationTime = 0.5f;
				vortexParticleEffect.Play(transform, (j >= 3) ? 0.25f : 0f);
			}
		}
		Attack attack = attackBox;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
	}

	public override void UpdateCalculatedDamage(bool initDamageOverride = false)
	{
		if (initDamageOverride)
		{
			attackBox.damageOverride = startAttackBoxDamageOverride;
		}
		projectileStatData = StatManager.GetSkillData(attackBox.atkInfo.skillCategory, attackBox.atkInfo.skillID);
		if (projectileStatData != null)
		{
			calculatedDamage = (int)(projectileCollisionModifier * (float)((attackBox.damageOverride < 0) ? Mathf.FloorToInt(projectileStatData.GetValue<int>(StatData.damageStr, 2)) : attackBox.damageOverride));
		}
	}
}
