using UnityEngine;

public class FireWall : Wave
{
	private new static GameObject prefab;

	private bool colliderFlip;

	private bool waveActive;

	[HideInInspector]
	public int hitCount = 30;

	[HideInInspector]
	public float hitInterval = 0.2f;

	private int hitStopwatch;

	private int middleWave;

	private float soundInterval = 1f;

	private int soundStopwatchID = -1;

	private AudioSource audioSource;

	private ParticleSystem[] fireWallEmitters;

	[HideInInspector]
	public bool lowParticleMode;

	private ParticleSystem.EmissionModule emitMod;

	private ParticleSystem.MinMaxCurve emitValue;

	private Vector2 effectVec;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/FireWall.prefab"));

	public override void Start()
	{
		base.Start();
		hitStopwatch = ChaosStopwatch.Begin(hitInterval, useInterval: true, hitInterval, hitCount);
		middleWave = Mathf.CeilToInt((float)wavePoolSize * 0.5f);
		fireWallEmitters = new ParticleSystem[wavePoolSize];
		for (int i = 0; i < wavePoolSize; i++)
		{
			fireWallEmitters[i] = wavePoolTrans[i].Find("FireEmitter").GetComponent<ParticleSystem>();
			if (lowParticleMode)
			{
				emitMod = fireWallEmitters[i].emission;
				emitValue = emitMod.rateOverTime;
				emitValue.constant *= 0.6f;
				emitMod.rateOverTime = emitValue;
			}
		}
	}

	public override void Update()
	{
		base.Update();
		if (!waveActive)
		{
			return;
		}
		if (ChaosStopwatch.Check(soundStopwatchID) && (audioSource == null || !audioSource.isPlaying) && wavePoolTrans[middleWave] != null)
		{
			soundStopwatchID = ChaosStopwatch.Begin(soundInterval);
			audioSource = SoundManager.PlayAudioWithDistance("FireWallLoop", wavePoolTrans[middleWave].position);
		}
		switch (ChaosStopwatch.CheckInterval(hitStopwatch))
		{
		case StopwatchState.Running:
			if (!colliderFlip)
			{
				colliderFlip = true;
				EnableAttackColliders(colliderFlip);
			}
			break;
		case StopwatchState.Ready:
			colliderFlip = false;
			EnableAttackColliders(colliderFlip);
			break;
		}
	}

	public override void ActivateWave()
	{
		base.ActivateWave();
		if (!layerMaskHit)
		{
			waveActive = true;
			effectVec = wavePoolTrans[waveCount].position;
			FireBurst poolItem = PoolManager.GetPoolItem<FireBurst>();
			int? particleCount = 3;
			Vector3? position = effectVec;
			Vector3? localEulerAngles = Globals.GetRotationVector(Vector2.up);
			poolItem.EmitDouble(particleCount, position, null, localEulerAngles);
			if (Globals.CheckCircle(effectVec, 0.5f, ChaosCollisions.layerPit))
			{
				PoolManager.GetPoolItem<ParticleEffect>("BurnMarkMedEmitter").Emit(1, effectVec, new ParticleSystemOverride
				{
					startLifetime = destroyDelay + 1.5f
				});
			}
		}
	}

	public override void DestroyWave()
	{
		ChaosStopwatch.Stop(destroyStopwatchID);
		if (setToDestroy && audioSource != null)
		{
			audioSource.Stop();
		}
		if (destroyInSequence && !destroySequenceStarted)
		{
			destroySequenceStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, spawnRate, wavePoolSize);
			destroySequenceStarted = true;
		}
		switch (ChaosStopwatch.CheckInterval(destroySequenceStopwatchID))
		{
		case StopwatchState.Ready:
			waveCount++;
			waveCount %= wavePoolSize;
			if (wavePoolAttacks[waveCount] != null && wavePoolAttacks[waveCount].collider != null)
			{
				wavePoolAttacks[waveCount].collider.gameObject.SetActive(value: false);
			}
			if (wavePoolTrans[waveCount] != null)
			{
				fireWallEmitters[waveCount].Stop();
				if (waveActive)
				{
					PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter").Emit(4, wavePoolTrans[waveCount].position + Vector3.up * 1.5f, SmokeEmitter.SmokeSmallOverride);
				}
			}
			if (wavePoolColDetectors[waveCount] != null)
			{
				wavePoolColDetectors[waveCount].SetActive(value: false);
			}
			break;
		case StopwatchState.Done:
			if (!setToDestroy && gameObject != null)
			{
				setToDestroy = true;
				Object.Destroy(gameObject, 1f);
			}
			break;
		}
	}

	public void EnableAttackColliders(bool status = true)
	{
		for (int i = 0; i < wavePoolSize; i++)
		{
			if (wavePoolAttacks[i] != null && wavePoolAttacks[i].collider != null)
			{
				wavePoolAttacks[i].collider.enabled = status;
			}
		}
	}
}
using UnityEngine;

public class HazardFireWall : Hazard
{
	private FireWall currentFW;

	public Vector2 spawnVector;

	public Vector2 attackVector;

	private Vector2 calcVector;

	public int waveCount = 10;

	public float waveDuration = 1f;

	public float waveSpacing = 0.75f;

	private ParticleSystem windupEmitter;

	private AudioSource burnAudio;

	public override void Awake()
	{
		base.Awake();
		Transform transform = base.transform.Find("WindupEmitter");
		if (transform != null)
		{
			windupEmitter = transform.GetComponent<ParticleSystem>();
		}
	}

	public override void Start()
	{
		base.Start();
		spawnVector = transform.position;
	}

	public override void OnDeactivated()
	{
		if (windupEmitter != null)
		{
			windupEmitter.Stop();
		}
		SetAudioStatus();
	}

	public override void OnWindup()
	{
		attackVector.Normalize();
		calcVector = spawnVector + attackVector * 0.5f;
		if (windupEmitter != null)
		{
			windupEmitter.transform.position = calcVector;
			windupEmitter.Play();
		}
		SetAudioStatus(givenStatus: true);
	}

	public override void OnActivated()
	{
		if (windupEmitter != null)
		{
			windupEmitter.Stop();
		}
		SetAudioStatus();
		currentFW = Globals.ChaosInst<FireWall>(FireWall.Prefab, transform, calcVector);
		currentFW.wavePoolSize = waveCount;
		currentFW.maxWaveCount = waveCount;
		currentFW.spacing = waveSpacing;
		currentFW.destroyDelay = waveDuration;
		currentFW.moveVector = attackVector;
		currentFW.spawnRate = 0.025f;
		currentFW.SetSkillData(Hazard.hazardSkillCategory, skillID);
		currentFW.spawnWaveThroughStopLayermask = true;
		currentFW.stopLayerMask = 0;
		currentFW.ignoreWaveCollisions = true;
	}

	private void SetAudioStatus(bool givenStatus = false, bool isWarmup = false)
	{
		if (burnAudio != null)
		{
			burnAudio.Stop();
			burnAudio = null;
		}
		if (givenStatus)
		{
			burnAudio = SoundManager.PlayIfNotPlaying("FireWallLoop", burnAudio, transform, useStdPitchOverride: false, -1f, 0.15f);
		}
	}
}

using System;
using System.Collections.Generic;
using UnityEngine;

public class Wave : MonoBehaviour
{
	public delegate void WaveStartEventHandler(Wave wave);

	public delegate void StopWaveEventHandler(Wave wave);

	public GameObject prefab;

	public string prefabFilePath = string.Empty;

	public Vector2 origin;

	public Vector2 moveVector;

	public Vector2 lastWavePosition;

	[HideInInspector]
	public Vector2 activationPosition;

	protected int waveCount;

	public int wavesElapsed;

	public int maxWaveCount = 5;

	public int wavePoolSize = 5;

	public bool lerpSpacing;

	public float lerpSpacingTime = 1f;

	protected int lerpStopwatchID = -1;

	public float initSpacing = 1f;

	public float spacing = 1f;

	protected float calculatedSpacing = 1f;

	public float initSpawnRate;

	public float spawnRate = 1f;

	public int spawnStopwatchID = -1;

	public bool spawnAtOrigin;

	public Transform spawnTransform;

	public string waveSkillCategory = string.Empty;

	public string waveSkillID = string.Empty;

	public int waveSkillLevel = -1;

	public bool waveIsUltimate;

	public AttackInfo waveAtkInfo;

	public float destroyDelay = 1f;

	protected int destroyStopwatchID = -1;

	protected bool destroyQueued;

	public bool destroyInSequence;

	protected bool destroySequenceStarted;

	protected int destroySequenceStopwatchID = -1;

	public bool destroyWaveOnStop = true;

	public string waveAnimName = string.Empty;

	public string waveSoundID = string.Empty;

	public bool playSoundOnce;

	public bool ignoreSoundTimeRestriction = true;

	protected bool soundPlayed;

	[HideInInspector]
	public int stopLayerMask;

	[HideInInspector]
	public bool hitStopLayerMask;

	protected bool layerMaskHit;

	protected float layerMaskRadius = 0.125f;

	protected Transform[] wavePoolTrans;

	protected Animator[] wavePoolAnims;

	protected Attack[] wavePoolAttacks;

	protected GameObject[] wavePoolColDetectors;

	protected bool setToDestroy;

	protected bool stopSpawning;

	public bool persistentWaves;

	public bool homing;

	public bool autoTarget;

	protected TargetInfo targetInfo;

	[HideInInspector]
	public Transform targetTrans;

	[HideInInspector]
	public List<GameObject> targetGroup;

	[HideInInspector]
	public List<GameObject> ignoreGroup;

	[HideInInspector]
	public GameObject parentObject;

	public float homingRange = 5f;

	public float homingDelay;

	private int homingStopwatchID;

	public int homingBias = 5;

	protected Vector2 homingVector;

	public bool stopWaveOnHit;

	protected bool collisionOccurred;

	public bool spawnWaveThroughStopLayermask;

	public bool ignoreWaveCollisions;

	public bool loseDamageOnCollisions = true;

	public bool waveCollideOnlyAtHead = true;

	public float collisionDetectRadius = 0.5f;

	private GameObject waveColliderDetector;

	public int calculatedDamage;

	public static WaveStartEventHandler globalWaveStartEventHandlers;

	public StopWaveEventHandler stopWaveEventHandler;

	private Wave otherWave;

	[HideInInspector]
	public bool IsSpawning => !stopSpawning;

	public virtual bool LoadPrefab()
	{
		if (prefab == null)
		{
			if (prefabFilePath == string.Empty)
			{
				return false;
			}
			prefab = ChaosBundle.Get(prefabFilePath);
		}
		return true;
	}

	public virtual void Awake()
	{
		if (!LoadPrefab())
		{
			gameObject.SetActive(value: false);
			return;
		}
		moveVector = Vector2.zero;
		stopLayerMask = ChaosCollisions.layerAll;
		hitStopLayerMask = false;
		if (waveCollideOnlyAtHead && !ignoreWaveCollisions)
		{
			waveColliderDetector = CreateWaveCollisionDetector(transform);
		}
	}

	public virtual GameObject CreateWaveCollisionDetector(Transform parentTrans)
	{
		WaveCollisionDetector waveCollisionDetector = Globals.ChaosInst<WaveCollisionDetector>(WaveCollisionDetector.Prefab, parentTrans, transform.position);
		waveCollisionDetector.waveCollisionEventHandler = (WaveCollisionDetector.WaveCollisionEventHandler)Delegate.Remove(waveCollisionDetector.waveCollisionEventHandler, new WaveCollisionDetector.WaveCollisionEventHandler(OnWaveCollision));
		waveCollisionDetector.waveCollisionEventHandler = (WaveCollisionDetector.WaveCollisionEventHandler)Delegate.Combine(waveCollisionDetector.waveCollisionEventHandler, new WaveCollisionDetector.WaveCollisionEventHandler(OnWaveCollision));
		waveCollisionDetector.parentWave = this;
		waveCollisionDetector.GetComponent<CircleCollider2D>().radius = collisionDetectRadius;
		return waveCollisionDetector.gameObject;
	}

	public virtual void Start()
	{
		if (globalWaveStartEventHandlers != null)
		{
			globalWaveStartEventHandlers(this);
		}
		origin = transform.position;
		wavePoolTrans = new Transform[wavePoolSize];
		wavePoolAnims = new Animator[wavePoolSize];
		wavePoolAttacks = new Attack[wavePoolSize];
		wavePoolColDetectors = new GameObject[wavePoolSize];
		int instanceID = base.gameObject.GetInstanceID();
		for (int i = 0; i < wavePoolSize; i++)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(prefab, transform.position, Quaternion.identity, transform);
			wavePoolTrans[i] = gameObject.transform;
			wavePoolAnims[i] = gameObject.GetComponent<Animator>();
			wavePoolAttacks[i] = gameObject.GetComponentInChildren<Attack>();
			if (wavePoolAttacks[i] != null)
			{
				Attack obj = wavePoolAttacks[i];
				obj.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(obj.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(HandleCollision));
				Attack obj2 = wavePoolAttacks[i];
				obj2.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(obj2.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(HandleCollision));
				wavePoolAttacks[i].AttackerObjID = instanceID;
			}
			gameObject.gameObject.SetActive(value: false);
			if (!waveCollideOnlyAtHead && !ignoreWaveCollisions)
			{
				wavePoolColDetectors[i] = CreateWaveCollisionDetector(gameObject.transform);
			}
		}
		InitStartCalculations();
	}

	public virtual void InitStartCalculations()
	{
		calculatedSpacing = ((!lerpSpacing) ? spacing : initSpacing);
		if (lerpSpacing)
		{
			lerpStopwatchID = ChaosStopwatch.Begin(lerpSpacingTime + initSpawnRate);
		}
		ref Vector2 reference = ref lastWavePosition;
		Vector2 vector = transform.position;
		Vector2 vector2;
		if (spawnAtOrigin)
		{
			vector2 = -moveVector * calculatedSpacing;
		}
		else
		{
			vector2 = ((!(initSpacing > 0f)) ? Vector2.zero : (-moveVector * (spacing - initSpacing)));
		}
		reference = vector + vector2;
		SetSkillData(waveSkillCategory, waveSkillID, waveSkillLevel, waveIsUltimate, apply: true);
		spawnStopwatchID = ChaosStopwatch.Begin(initSpawnRate, useInterval: true, spawnRate, maxWaveCount);
		if (homing && homingBias != 0)
		{
			InitHomingVars();
		}
	}

	public virtual void InitHomingVars()
	{
		homingVector = moveVector;
		homingStopwatchID = ChaosStopwatch.Begin(homingDelay);
	}

	public virtual void SetSkillData(string skillCategory, string skillID, int skillLevel = -1, bool isUltimate = false, bool apply = false)
	{
		waveSkillCategory = skillCategory;
		waveSkillID = skillID;
		waveSkillLevel = skillLevel;
		waveIsUltimate = isUltimate;
		StatData skillData = StatManager.GetSkillData(waveSkillCategory, waveSkillID);
		if (skillData != null)
		{
			calculatedDamage = skillData.GetValue<int>("damage");
		}
		if (apply)
		{
			ApplySkillData();
		}
	}

	public virtual void ApplySkillData()
	{
		for (int i = 0; i < wavePoolAttacks.Length; i++)
		{
			if (!(wavePoolAttacks[i] == null))
			{
				wavePoolAttacks[i].SetAttackInfo(waveSkillCategory, waveSkillID, waveSkillLevel, waveIsUltimate);
				if (waveAtkInfo == null)
				{
					waveAtkInfo = new AttackInfo(wavePoolAttacks[i].atkInfo);
				}
			}
		}
	}

	public virtual void ApplyDamageOverride(int damageOverride)
	{
		if (!loseDamageOnCollisions)
		{
			return;
		}
		calculatedDamage = damageOverride;
		if (calculatedDamage <= 0)
		{
			calculatedDamage = 0;
			StopWave();
			destroyQueued = true;
			DestroyWave();
		}
		if (wavePoolAttacks == null)
		{
			return;
		}
		for (int i = 0; i < wavePoolAttacks.Length; i++)
		{
			if (!(wavePoolAttacks[i] == null))
			{
				wavePoolAttacks[i].damageOverride = calculatedDamage;
			}
		}
	}

	public virtual void ChangeInterval(float newInterval, int newMax = -1, float newInit = -1f)
	{
		spawnRate = newInterval;
		spawnStopwatchID = ChaosStopwatch.Begin((!(newInit > 0f)) ? 0f : newInit, useInterval: true, spawnRate, (newMax <= 0) ? (maxWaveCount - wavesElapsed) : newMax);
	}

	public virtual void Update()
	{
		if (destroyQueued && ChaosStopwatch.Check(destroyStopwatchID))
		{
			DestroyWave();
		}
	}

	public virtual void FixedUpdate()
	{
		if (destroyQueued)
		{
			return;
		}
		if (lerpSpacing)
		{
			HandleLerpSpacing();
		}
		switch (ChaosStopwatch.CheckInterval(spawnStopwatchID))
		{
		case StopwatchState.Ready:
			if (!stopSpawning)
			{
				ActivateWave();
			}
			break;
		case StopwatchState.Done:
			destroyQueued = true;
			destroyStopwatchID = ChaosStopwatch.Begin(destroyDelay);
			StopWave();
			break;
		}
	}

	public virtual void DestroyWave()
	{
		ChaosStopwatch.Stop(destroyStopwatchID);
		if (destroyInSequence && !destroySequenceStarted)
		{
			destroySequenceStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, spawnRate, wavePoolSize);
			destroySequenceStarted = true;
		}
		switch (ChaosStopwatch.CheckInterval(destroySequenceStopwatchID))
		{
		case StopwatchState.Ready:
			waveCount++;
			waveCount %= wavePoolSize;
			DestroyColumn(waveCount);
			break;
		case StopwatchState.Done:
			if (!setToDestroy && gameObject != null)
			{
				setToDestroy = true;
				if (destroyWaveOnStop)
				{
					UnityEngine.Object.Destroy(gameObject);
				}
				else
				{
					gameObject.SetActive(value: false);
				}
			}
			break;
		}
		for (int i = 0; i < wavePoolSize; i++)
		{
			if (wavePoolAttacks[i] != null)
			{
				Attack obj = wavePoolAttacks[i];
				obj.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(obj.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(HandleCollision));
			}
		}
	}

	public virtual void DestroyColumn(int waveCount)
	{
		if (wavePoolTrans[waveCount] != null)
		{
			if (destroyWaveOnStop)
			{
				UnityEngine.Object.Destroy(wavePoolTrans[waveCount].gameObject);
			}
			else
			{
				wavePoolTrans[waveCount].gameObject.SetActive(value: false);
			}
		}
	}

	public virtual void HandleLerpSpacing()
	{
		lerpSpacing = !ChaosStopwatch.Check(lerpStopwatchID);
		calculatedSpacing = Mathf.Lerp(spacing, initSpacing, Mathf.Pow(ChaosStopwatch.GetRemainingTime(lerpStopwatchID) / lerpSpacingTime, 2f));
	}

	public virtual void ActivateWave()
	{
		wavesElapsed++;
		waveCount++;
		waveCount %= wavePoolSize;
		if (homing && ChaosStopwatch.Check(homingStopwatchID))
		{
			moveVector = GetHomingVector(lastWavePosition);
		}
		if (spawnTransform == null)
		{
			activationPosition = lastWavePosition + moveVector * calculatedSpacing;
		}
		else
		{
			activationPosition = spawnTransform.position;
			moveVector = (activationPosition - lastWavePosition).normalized;
		}
		lastWavePosition = activationPosition;
		layerMaskHit = !Globals.CheckCircle(activationPosition, layerMaskRadius, stopLayerMask);
		hitStopLayerMask = false;
		if (layerMaskHit)
		{
			hitStopLayerMask = !spawnWaveThroughStopLayermask;
			StopWave(!spawnWaveThroughStopLayermask);
			return;
		}
		if (waveCollideOnlyAtHead && waveColliderDetector != null)
		{
			waveColliderDetector.transform.position = activationPosition;
		}
		wavePoolTrans[waveCount].position = activationPosition;
		wavePoolTrans[waveCount].gameObject.SetActive(value: true);
		if (wavePoolAttacks[waveCount] != null)
		{
			wavePoolAttacks[waveCount].knockbackOverwriteVector = moveVector;
		}
		if (wavePoolAnims[waveCount] != null && waveAnimName != string.Empty)
		{
			wavePoolAnims[waveCount].Play(waveAnimName, -1, 0f);
		}
		if (waveSoundID != string.Empty && (!playSoundOnce || !soundPlayed))
		{
			soundPlayed = true;
			string audioID = waveSoundID;
			Vector2? soundOrigin = activationPosition;
			float standardPitchRange = SoundManager.StandardPitchRange;
			bool ignoreTimeRestriction = ignoreSoundTimeRestriction;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange, ignoreTimeRestriction);
		}
	}

	public virtual Vector2 GetHomingVector(Vector2 wavePosition)
	{
		if (autoTarget)
		{
			targetInfo = Entity.GetClosestTarget(targetGroup, wavePosition, homingRange, playerTagOnly: false, ignoreGroup, parentObject);
			if (targetInfo != null)
			{
				targetTrans = targetInfo.transform;
			}
		}
		homingVector = (homingVector * (homingBias - 1) + ((!(targetTrans != null)) ? moveVector : ((Vector2)targetTrans.position - wavePosition)).normalized) / homingBias;
		return homingVector;
	}

	public virtual void HandleCollision(Collider2D other)
	{
		if (!collisionOccurred && stopWaveOnHit)
		{
			collisionOccurred = true;
			StopWave();
		}
	}

	public virtual void OnWaveCollision(Collider2D other)
	{
		if (!ignoreWaveCollisions && loseDamageOnCollisions && (!stopSpawning || persistentWaves) && !(other.transform == null) && !(other.transform.parent == null) && !(other.transform.parent.parent == null) && !(other.transform.parent.parent == transform))
		{
			otherWave = other.transform.parent.parent.GetComponent<Wave>();
			if (!(otherWave == null) && !(otherWave.waveSkillCategory == waveSkillCategory) && !otherWave.ignoreWaveCollisions && (GameController.pvpOn || !waveSkillCategory.Contains("Player") || !otherWave.waveSkillCategory.Contains("Player")) && (!otherWave.stopSpawning || otherWave.persistentWaves))
			{
				int num = calculatedDamage - otherWave.calculatedDamage;
				ApplyDamageOverride(num);
				otherWave.ApplyDamageOverride(-num);
				PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Large, lastWavePosition, lastWavePosition);
				HandleCollision(other);
			}
		}
	}

	public virtual void StopWave(bool stop = true)
	{
		stopSpawning = stop;
		if (stop && stopWaveEventHandler != null)
		{
			stopWaveEventHandler(this);
		}
	}

	public virtual void OnNegate()
	{
		StopWave();
		if (wavesElapsed == 1)
		{
			destroyQueued = true;
			DestroyWave();
		}
	}

	public virtual void ResetWave()
	{
		destroySequenceStopwatchID = -1;
		DestroyWave();
		destroyQueued = false;
		destroySequenceStarted = false;
		soundPlayed = false;
		hitStopLayerMask = false;
		layerMaskHit = false;
		setToDestroy = false;
		stopSpawning = false;
		collisionOccurred = false;
		waveCount = 0;
		wavesElapsed = 0;
		InitStartCalculations();
		gameObject.SetActive(value: true);
	}
}

	public class SummonMeteorStrikeState : SkillState
	{
		public new static string staticID = "SummonMeteorStrike";

		private string dropDirStr = string.Empty;

		private string rainDirStr = string.Empty;

		private Vector2 dropPosition;

		private MeteorStrike currentMS;

		private bool effectsPlayed;

		private AttackInfo mainInfo;

		private AttackInfo rainInfo;

		private bool useUlt;

		private MeteorRainCloud curMeteorCloud;

		public override string OnEnterAnimStr => parent.GSlamAnimStr;

		public SummonMeteorStrikeState(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			SetAnimTimes(0f, 0.2f, 0.05f, 0.5f, 0.7f);
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			switch (parent.facingDirection)
			{
			case FacingDirection.Right:
				dropDirStr = "DropLeft";
				rainDirStr = "DropRight";
				break;
			case FacingDirection.Left:
				dropDirStr = "DropRight";
				rainDirStr = "DropLeft";
				break;
			default:
				dropDirStr = "Drop";
				rainDirStr = "Drop";
				break;
			}
			effectsPlayed = false;
			useUlt = isUltimate;
			mainInfo = AttackInfo.GetInfoFromData(parent, skillData, (!IsEmpowered) ? 1 : 2, useUlt);
			rainInfo = AttackInfo.GetInfoFromData(parent, skillData, 3, useUlt);
			dropPosition = Globals.GetSafeLinecastVector(parent.transform.position, inputVector, 3.5f, ChaosCollisions.layerAllWall);
			CreateMeteorStrike(dropPosition);
			if (IsEmpowered)
			{
				CreateMeteorCloud(dropPosition);
			}
			if (useUlt)
			{
				parent.StartCoroutine(CreateMeteorStorm(dropPosition, inputVector));
			}
		}

		private void CreateMeteorStrike(Vector2 givenPosition)
		{
			currentMS = PoolManager.GetPoolItem<MeteorStrike>();
			currentMS.Initialize(givenPosition, !useUlt);
			currentMS.attack.SetAttackInfo(mainInfo);
			currentMS.anim.speed = 1.25f;
			currentMS.forceAnimDirection = dropDirStr;
		}

		private void CreateMeteorCloud(Vector2 givenPosition, int givenCount = 5, bool useReducedEffects = false, bool usePlayerPos = false)
		{
			curMeteorCloud = ChaosInst<MeteorRainCloud>(MeteorRainCloud.Prefab, givenPosition);
			curMeteorCloud.SetSkillInfo(rainInfo, rainDirStr, givenCount);
			curMeteorCloud.useReducedEffects = useReducedEffects;
			curMeteorCloud.playerPos = ((!usePlayerPos) ? Vector3.zero : parent.transform.position);
		}

		private IEnumerator CreateMeteorStorm(Vector2 givenPosition, Vector2 givenVector)
		{
			List<Vector2> locList = new List<Vector2>();
			for (int i = 0; i < 12; i++)
			{
				Vector2 checkVector = Globals.GetRotatedCircleVector(12, i, givenVector);
				Vector2 checkLocation;
				if (i % 2 == 0)
				{
					checkLocation = givenPosition + checkVector * 5f;
					locList.Add(checkLocation);
					CreateMeteorCloud(checkLocation, 12, useReducedEffects: true, usePlayerPos: true);
				}
				checkLocation = Globals.GetFailSafeLinecastVector(givenPosition, checkVector, 10f, ChaosCollisions.layerAllWall);
				if (checkLocation != givenPosition)
				{
					locList.Add(checkLocation);
					CreateMeteorCloud(checkLocation, 12, useReducedEffects: true, usePlayerPos: true);
				}
				yield return null;
			}
			locList.Shuffle();
			while (locList.Count > 0)
			{
				CreateMeteorStrike(locList[0]);
				locList.RemoveAt(0);
				if (Globals.RandBool && locList.Count > 0)
				{
					CreateMeteorStrike(locList[0]);
					locList.RemoveAt(0);
				}
				yield return Globals.waitFor0p1;
			}
			locList.Clear();
		}

		public override void ConcludeSkill()
		{
			if (!effectsPlayed && parent.anim.AnimPlayed(0.3f))
			{
				effectsPlayed = true;
				dropPosition = parent.transform.position;
				DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
				int particleCount = 10;
				float scale = 0.25f;
				Vector3? emitPosition = dropPosition;
				poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
				PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter").Emit(3, dropPosition + inputVector);
				SoundManager.PlayAudioWithDistance("SummonRock", dropPosition);
				CameraController.ShakeCamera(0.3f);
			}
			base.ConcludeSkill();
		}
	}

