		{
			initLocArr = new Vector2[5];
			for (int i = 0; i < 5; i++)
			{
				ref Vector2 reference = ref initLocArr[i];
				reference = Globals.GetCirclePositionVector(5, i) * 1.5f;
			}
			dropLocArr = new Vector2[dropLocCount];
			for (int j = 0; j < dropIndex; j++)
			{
