		if (playerPos != Vector3.zero)
		{
			tempColorVal = Globals.LerpWithRange(-5f, 5f, playerPos.y - transform.position.y, 0.6f, 1.25f);
			curMeteorRain.sprite.color = new Color(tempColorVal, tempColorVal, 1f);
