	}

	private void HandleCircleSprite()
	{
		if (useCastCircle && circleSprite != null)
		{
			colorLerpValue = spriteStopwatch.TimePercentage;
			if (colorLerpValue >= 1f)
			{
				colorFlip = !colorFlip;
				spriteStopwatch.IsRunning = true;
			}
			circleSprite.color = ((!colorFlip) ? Color.Lerp(fullColor, emptyColor, spriteStopwatch.TimePercentage) : Color.Lerp(emptyColor, fullColor, spriteStopwatch.TimePercentage));
		}
	}

	public void SetSkillInfo(AttackInfo givenInfo, string givenAnim, int givenCount = 5)
	{
		atkInfo = givenInfo;
		skillAnim = givenAnim;
		rainCount = givenCount;
	}
