using System;
using UnityEngine;

public class FlameTrap : MonoBehaviour
{
	private static GameObject prefab;

	public Animator anim;

	public Attack attack;

	public CircleCollider2D attackCollider;

	public ParticleSystem smokeEmitter;

	public ParticleSystem idlePartSys;

	public ParticleSystem idlePartSysSecond;

	public ParticleSystem waitPartSys;

	public ParticleSystem activePartSys;

	public ParticleSystem activePartSysSecond;

	public float lifeTime = 8f;

	private int lifeStopwatchID;

	public int hitCount = 6;

	public float hitInterval = 0.15f;

	private int hitStopwatchID;

	private bool targetHit;

	private float destroyTime = 0.5f;

	private bool destroyQueued;

	private string skillCategory;

	private string skillID;

	private Vector2 currentPosition;

	private AudioSource idleAudio;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/FlameTrap.prefab"));

	private void Start()
	{
		lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
		Attack attack = this.attack;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
		anim.Play("Idle");
		attackCollider.enabled = true;
		activePartSys.Emit(8);
		activePartSysSecond.Emit(4);
		waitPartSys.Play();
		currentPosition = transform.position;
		FireExplosion.SpawnExplosion(currentPosition, 0.5f, 0.5f);
		PoolManager.GetPoolItem<FireBurst>().EmitSingle(7, currentPosition, null, Vector3.up);
		SoundManager.PlayWithDistAndSPR("FireArcEnd", currentPosition);
		CameraController.ShakeCamera(0.1f);
	}

	private void FixedUpdate()
	{
		if (destroyQueued)
		{
			return;
		}
		if (targetHit)
		{
			switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
			{
			case StopwatchState.Running:
				attackCollider.enabled = true;
				break;
			case StopwatchState.Ready:
				attackCollider.enabled = false;
				FireExplosion.SpawnExplosion(currentPosition, 0.5f, 0.5f);
				SoundManager.PlayWithDistAndSPR("FireArcEnd", currentPosition);
				break;
			case StopwatchState.Done:
				Reset();
				break;
			}
		}
		else if (ChaosStopwatch.Check(lifeStopwatchID))
		{
			Reset();
		}
	}

	private void Update()
	{
		if (!destroyQueued)
		{
			idleAudio = SoundManager.PlayIfNotPlaying("FlameTrapIdle", idleAudio, transform);
		}
	}

	private void Reset()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			UnityEngine.Object.Destroy(gameObject, destroyTime);
			if (idleAudio != null)
			{
				idleAudio.Stop();
				idleAudio = null;
			}
			anim.Play("End");
			idlePartSys.Stop();
			idlePartSysSecond.Stop();
			smokeEmitter.Stop();
			waitPartSys.Stop();
			activePartSys.Emit(10);
			activePartSysSecond.Emit(10);
			activePartSys.Stop();
			activePartSysSecond.Stop();
			SoundManager.PlayWithDistAndSPR("FlameLight", currentPosition);
			PoolManager.GetPoolItem<ParticleEffect>("BurnMarkMedEmitter").Emit(1, currentPosition + Vector2.down * 0.25f, ParticleEffectOverrides.StartLifeTimeTwo);
			PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter").Emit(2, currentPosition + Vector2.up * 1.5f);
		}
	}

	private void OnTargetHit(Collider2D givenCol)
	{
		targetHit = true;
		hitStopwatchID = ChaosStopwatch.Begin(hitInterval, useInterval: true, hitInterval, hitCount);
		Attack attack = this.attack;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
		FlameBurst.CreateBurst(transform.position, skillCategory, skillID, 2, 2f);
		anim.Play("Active");
		smokeEmitter.Stop();
		idlePartSys.Stop();
		idlePartSysSecond.Stop();
		waitPartSys.Stop();
		activePartSys.Play();
		activePartSysSecond.Play();
	}

	public void SetInfo(string givenCategory, string givenID)
	{
		skillCategory = givenCategory;
		skillID = givenID;
		attack.SetAttackInfo(skillCategory, skillID);
	}
}

