		currentPosition = parent.transform.position;
		parent.anim.PlayDirectional(OnEnterAnimStr, -1, animStartTime);
		parent.ToggleEnemyFloorCollisions(status: false);
		fallAnimPlayed = false;
		atkInterval = Mathf.Max(0.05f, jumpTime * jumpBalance / (float)atkCount);
		atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, atkInterval, atkCount);
		attackCircle = ChaosInst<Attack>(Attack.CirclePrefab, currentPosition);
		SetAttackInfo(attackCircle);
		attackCol = attackCircle.GetComponent<CircleCollider2D>();
		attackCol.radius = atkRadius;
