		flameRingFloor.Play(120f, currentPosition);
		vortexInterval = atkInterval * 7.5f;
		for (int i = 0; i < vortexCount; i++)
		{
			vortEffects[i] = PoolManager.GetPoolItem<VortexParticleEffect>("FireVortexEffect");
			fireVortexEffect = vortEffects[i];
			fireVortexEffect.startAngleRange = Vector2.one * i * vortexAngleMult;
			fireVortexEffect.startRadius = atkRadius - 0.125f;
			fireVortexEffect.rotationTime = vortexInterval;
			fireVortexEffect.Play(parent.transform, (i >= vortexHalfCount) ? (vortexInterval * 0.5f) : 0f);
		}
		spawnCount = 0;
