			}
			slamQueued = false;
			attackCircle.ChangeAttackInfoLevel(burstAtkLevel);
			attackCircle.EnableForOneFrame(destroyOnDisable: true);
			currentPosition = parent.transform.position;
			CameraController.ShakeCamera(0.4f);
			PoolManager.GetPoolItem<ParticleEffect>("FlameCircleBurstEmitter").Emit(40, currentPosition, (!isUltimate) ? ParticleEffectOverrides.RadiusTwo : ParticleEffectOverrides.Radius2p5);
