		private float beamRange = 7.5f;

		private float beamArcTime = 1f;

		private bool beamFired;

		private bool beamStopped;

		private int delayStopwatchID;

		private int ultStopwatchID;

		private bool ultStarted;

		public override string OnEnterAnimStr => (!isUltimate) ? parent.PBAoEAnimStr : parent.ForehandAnimStr;

		public UseFireBeam(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			SetAnimTimes(0.1f, 0.2f, 0.25f, 0.55f, 0.75f);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			perpendVec = Globals.GetPerpendicular(inputVector);
			beamFired = false;
			beamStopped = false;
			if (isUltimate)
			{
				SetSkillLevel(3);
				animStartTime = animExecTime;
				beamThickness = 0.75f;
				beamRange = 16f;
				beamArcTime = 1.125f;
				ultStarted = false;
			}
			else
			{
				animStartTime = 0.1f;
				if (IsEmpowered)
				{
					SetSkillLevel(2);
					beamThickness = 1f;
					beamRange = 10f;
					perpendVec *= 0.5f;
					beamArcTime = 0.75f;
				}
				else
				{
					SetSkillLevel(1);
					beamThickness = 0.75f;
					beamRange = 8f;
					perpendVec *= 0.25f;
					beamArcTime = 0.625f;
				}
			}
			CameraController.ShakeCamera(0.25f);
		}

		public override void ExecuteSkill()
		{
			if (beamFired)
			{
				if (ChaosStopwatch.Check(delayStopwatchID))
				{
					base.ExecuteSkill();
					beamStopped = true;
				}
				else if (parent.anim.AnimPlayed(0.45f))
				{
					parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, 0.3f);
				}
			}
			else if (isUltimate)
			{
				if (!ultStarted)
				{
					ultStarted = true;
					ultStopwatchID = ChaosStopwatch.Begin(0.15f, useInterval: true, 0.15f, 6);
					CreateBeamArc(parent.forehandAnimPlayed);
					return;
				}
				switch (ChaosStopwatch.CheckInterval(ultStopwatchID))
				{
				case StopwatchState.Ready:
					if (ChaosStopwatch.GetRemainingIntervals(ultStopwatchID) == 0)
					{
						parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, 0.25f);
						beamThickness = 1.5f;
						beamArcTime = 1f;
						SetSkillLevel(4);
						parent.StartCoroutine(FireBeamArc(inputVector, perpendVec, usePower: true));
						parent.StartCoroutine(FireBeamArc(inputVector, -perpendVec, usePower: true));
					}
					else
					{
						parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, 0.25f);
						CreateBeamArc(parent.forehandAnimPlayed);
					}
					break;
				case StopwatchState.Done:
					beamFired = true;
					delayStopwatchID = ChaosStopwatch.Begin(beamArcTime * 0.75f);
					break;
				}
			}
			else
			{
				beamFired = true;
				delayStopwatchID = ChaosStopwatch.Begin(beamArcTime * 0.75f);
				CreateBeamArc(givenStatus: true);
				CreateBeamArc(givenStatus: false);
			}
			CancelToDash();
		}

		public override void OnExit()
		{
			base.OnExit();
			beamStopped = true;
		}

		private FireBeam CreateFireBeam(Vector2 givenPosition, Vector2 givenVector)
		{
			currentFB = ChaosInst<FireBeam>(FireBeam.Prefab, givenPosition + givenVector * 0.5f, Globals.GetRotationQuaternion(givenVector));
			currentFB.attack.SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
			currentFB.attack.knockbackOverwriteVector = givenVector;
			currentFB.hitCount = 12;
			currentFB.hitInterval = 0.1f;
			currentFB.beamThickness = beamThickness;
			currentFB.maxRange = beamRange;
			return currentFB;
		}

		private void CreateBeamArc(bool givenStatus)
		{
			calcVec = ((!givenStatus) ? (-perpendVec) : perpendVec);
			parent.StartCoroutine(FireBeamArc((inputVector - calcVec * 0.5f).normalized, calcVec));
		}

		private IEnumerator FireBeamArc(Vector2 givenStart, Vector2 givenEnd, bool usePower = false)
		{
			Vector2 tempPosition = parent.attackOriginTrans.position;
			FireBeam tempBeam = CreateFireBeam(tempPosition + givenStart, givenStart);
			int arcStopwatchID = ChaosStopwatch.Begin(beamArcTime);
			float lerpValue = 0f;
			while (!beamStopped && tempBeam != null && lerpValue < 1f)
			{
				tempPosition = parent.attackOriginTrans.position;
				lerpValue = ChaosStopwatch.GetTimePercentage(arcStopwatchID);
				if (usePower)
				{
					lerpValue = Mathf.Pow(lerpValue, 3f);
				}
				Vector2 lerpVector = Vector2.Lerp(givenStart, givenEnd, lerpValue);
				tempBeam.transform.position = tempPosition + lerpVector;
				tempBeam.transform.localEulerAngles = Globals.GetRotationVector(lerpVector);
				yield return null;
			}
			if (tempBeam != null)
			{
				tempBeam.StopBeam();
			}
		}
	}

