		leftPSys.Emit((int)(currentRange * 0.7f));
	}

	private void HandleAudio(bool status = true)
	{
		if (status)
		{
			if (beamAudio == null || !beamAudio.isPlaying)
			{
				beamAudio = SoundManager.PlayAudioWithDistance("IgnitionOrbLoop", transform.position);
			}
		}
		else if (beamAudio != null)
		{
			beamAudio.Stop();
			beamAudio = null;
		}
	}
