public virtual void UpdateRangeVars()
{
	currentPosition = transform.position;
	if (currentMaxRange < maxRange)
	{
		currentMaxRange = Mathf.Clamp(currentMaxRange + Time.fixedDeltaTime * travelSpeed, 1f, maxRange);
	}
	else
	{
		currentMaxRange = maxRange;
	}
	beamTipTrans.localPosition = new Vector2(0f, currentMaxRange);
	targetPosition = Globals.GetLinecastVector(currentPosition, beamTipTrans.position, ChaosCollisions.layerUpperWallAndObst);
