	beamSprite.transform.localScale = new Vector3(beamThickness * 0.5f, currentRange * 16f, 1f);
	atkSizeVector.y = currentRange;
	attackCollider.size = atkSizeVector;
	atkOffsetVector.y = currentRange * 0.5f;
	attackCollider.offset = atkOffsetVector;
