using UnityEngine;

public class MagmaBomb : MonoBehaviour
{
	private static GameObject _prefab;

	private static float minSpeed = 5f;

	private static float maxSpeed = 15f;

	private ChaosQuickStopwatch moveStopwatch = new ChaosQuickStopwatch();

	private float moveLerpValue;

	private bool moveCompleted;

	public Animator anim;

	public SpriteRenderer circleSprite;

	public Movement movement;

	private string skillCategory = string.Empty;

	private string skillID = string.Empty;

	private float lifeTime = 2.5f;

	private float primeTime = 0.5f;

	private float blastRadius = 2.5f;

	private int lifeStopwatchID;

	private int primeStopwatchID;

	private bool primed;

	private bool detonated;

	private ChaosQuickStopwatch targetStopwatch = new ChaosQuickStopwatch(0.25f);

	private Entity currentEntity;

	private TargetInfo currentInfo;

	private Vector2 currentPosition;

	private static AudioSource burnAudio;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/MagmaBomb.prefab");
			}
			return _prefab;
		}
	}

	public void Initialize(string givenCat, string givenID, bool isEmp)
	{
		skillCategory = givenCat;
		skillID = givenID;
		if (isEmp)
		{
			lifeTime = 4f;
			primeTime = 0.3f;
			blastRadius = 3f;
		}
	}

	private void Start()
	{
		circleSprite.transform.localScale = new Vector3(blastRadius * 0.25f, blastRadius * 0.25f, 1f);
		lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
		primeStopwatchID = ChaosStopwatch.Begin(primeTime);
		movement.moveSpeedStat.syncCurrentToModMax = false;
		movement.moveSpeedStat.ModifiedValue = maxSpeed;
		movement.moveSpeedStat.CurrentValue = minSpeed;
		SoundManager.PlayAudioWithDistance("FlameCast", transform.position);
	}

	private void Update()
	{
		if (detonated)
		{
			return;
		}
		if (ChaosStopwatch.Check(lifeStopwatchID))
		{
			Detonate();
			return;
		}
		if (!primed)
		{
			if (!ChaosStopwatch.Check(primeStopwatchID))
			{
				return;
			}
			primed = true;
			anim.Play("Idle", -1, 0f);
			currentPosition = transform.position;
			PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter").Emit(8, currentPosition + Vector2.up * 1.5f);
			PoolManager.GetPoolItem<ParticleEffect>("SmokeSmallEmitter").Emit(3, currentPosition + Vector2.up * 2f);
			PoolManager.GetPoolItem<ParticleEffect>("FlameCircleBurstEmitter").Emit(10, currentPosition + Vector2.up, ParticleEffectOverrides.Radius0p1);
			SoundManager.PlayAudioWithDistance("IgnitionOrbForm", currentPosition);
		}
		HandleAudio();
		if (currentEntity == null && !targetStopwatch.IsRunning)
		{
			targetStopwatch.IsRunning = true;
			currentInfo = Entity.GetClosestTarget(GameController.enemies, transform.position, blastRadius + 1f, playerTagOnly: false, null, null, requireLOS: true);
			if (currentInfo != null)
			{
				currentEntity = currentInfo.entity;
				circleSprite.enabled = false;
				movement.moveSpeedStat.CurrentValue = minSpeed;
				moveStopwatch.IsRunning = true;
				moveCompleted = false;
			}
			else
			{
				circleSprite.enabled = true;
			}
		}
	}

	private void FixedUpdate()
	{
		if (!detonated && primed && !(currentEntity == null))
		{
			if (movement.MoveToTarget(currentEntity.transform.position, 1f))
			{
				Detonate();
			}
			else if (!moveCompleted)
			{
				moveLerpValue = moveStopwatch.TimePercentage;
				movement.moveSpeedStat.CurrentValue = Mathf.Lerp(minSpeed, maxSpeed, Mathf.Pow(moveLerpValue, 2f));
				moveCompleted = moveLerpValue >= 1f;
			}
		}
	}

	private void HandleAudio(bool status = true)
	{
		if (status)
		{
			if (burnAudio == null || !burnAudio.isPlaying)
			{
				burnAudio = SoundManager.PlayAudioWithDistance("IgnitionOrbLoop", transform.position);
			}
		}
		else if (burnAudio != null)
		{
			burnAudio.Stop();
			burnAudio = null;
		}
	}

	private void Detonate()
	{
		if (!detonated)
		{
			detonated = true;
			currentPosition = transform.position;
			FlameBurst.CreateBurst(currentPosition, skillCategory, skillID, 1, blastRadius);
			PoolManager.GetPoolItem<ParticleEffect>("FlameCircleBurstEmitter").Emit((int)(8f * blastRadius), currentPosition, new ParticleSystemOverride
			{
				radius = blastRadius
			});
			PoolManager.GetPoolItem<ParticleEffect>("BurnMarkLargeEmitter").Emit(1, currentPosition);
			PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter").Emit(5, currentPosition + Vector2.up);
			CameraController.ShakeCamera(0.2f);
			HandleAudio(status: false);
			SoundManager.PlayWithDistAndSPR("FireBlast", currentPosition);
			if (gameObject != null)
			{
				Object.Destroy(gameObject);
			}
		}
	}
}

