			}
		}

		private void HandleParticleTrail(Vector2 givenPosition)
		{
			if (!(this.fireBurst == null))
			{
				particleCounter = Mathf.Max(2, particleCounter - 1);
				FireBurst fireBurst = this.fireBurst;
				int? particleCount = particleCounter;
				Vector3? position = givenPosition;
				Vector3? localEulerAngles = currentRotation;
				fireBurst.EmitSingle(particleCount, position, null, localEulerAngles);
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.movement.dashSpeedStat.RemoveMod(speedMod);
			parent.movement.dashDurationStat.RemoveMod(durationMod);
			CleanUpObjects();
		}

		private void CleanUpObjects()
		{
			if (currentAtk != null)
			{
				Attack attack = currentAtk;
				attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
				currentAtk = null;
			}
			if (currentAtkObj != null)
			{
				UnityEngine.Object.Destroy(currentAtkObj);
				currentAtkObj = null;
			}
			if (fireBurst != null && fireBurst.gameObject != null)
			{
				UnityEngine.Object.Destroy(fireBurst.gameObject, 2f);
				fireBurst = null;
			}
		}

		private void OnTargetHit(Entity givenEnt)
		{
			if (!targetHit)
			{
				targetHit = true;
				finishedDashing = true;
				parent.movement.MoveToMoveVector((!IsEmpowered) ? 10f : 20f);
				ChaosInst<FlameWolfEffect>(FlameWolfEffect.Prefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(inputVector)).playHitEffect = true;
				CleanUpObjects();
				parent.anim.PlayDirectional(parent.SlideAnimStr);
				atkStopwatchID = ChaosStopwatch.Begin((!(givenEnt == null)) ? 0.15f : 0.08f);
				FlameBurst.CreateBurst(parent.attackOriginTrans.position, string.Empty, string.Empty, 1, 0.5f);
				CameraController.ShakeCamera(0.3f);
			}
		}

		private void CreateAttackBurst(Vector2 givenPosition, bool givenEmp)
		{
			currentFB = ChaosInst<FireBlast>(FireBlast.Prefab, givenPosition - inputVector * 0.5f, Globals.GetRotationQuaternion(inputVector));
			currentFB.attack.knockbackOverwriteVector = inputVector;
			currentFB.anim.speed = 2f;
			currentFB.skipParticleEmission = true;
			givenPosition += inputVector;
			if (givenEmp)
			{
				currentFB.attack.SetAttackInfo(parent.skillCategory, skillID, 2);
				FireExplosion.SpawnExplosion(givenPosition, 1f, 1f, 25, 15);
			}
			else
			{
				currentFB.attack.SetAttackInfo(parent.skillCategory, skillID, 3);
				FireExplosion.SpawnExplosion(givenPosition, 2f, 1f, 40, 25);
			}
			ChaosInst<FlameWolfEffect>(FlameWolfEffect.Prefab, givenPosition, Globals.GetRotationQuaternion(inputVector));
			FlameBurst.CreateBurst(givenPosition, string.Empty, string.Empty);
			SoundManager.PlayWithDistAndSPR("FireBlast", givenPosition, 1.2f);
			SoundManager.PlayWithDistAndSPR("FireWallStart", givenPosition);
			CameraController.ShakeCamera(0.5f);
		}
	}

