public class UseFlamePunch : BaseJumpState
{
	public new static string staticID = "UseFlamePunch";

	private Vector2 currentPosition;

	private Quaternion currentQuat;

	private FlamePunch currentFP;

	private float baseScale;

	private float finalScale;

	private int hitStopwatchID;

	private int hitCounter;

	private int maxHitCount;

	private float hitDelay;

	private NumVarStatMod dashSpdMod;

	private NumVarStatMod dashDurMod;

	private bool movementStopped;

	private bool jumpStarted;

	private bool spinAnimPlayed;

	public override string OnEnterAnimStr => parent.KickAnimStr;

	public UseFlamePunch(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isMeleeSkill = true;
		startCooldownOnEnter = false;
		useSmartCD = true;
		SetAnimTimes(0.25f, 0.2f, 0.35f, 0.55f, 0.75f);
		dashSpdMod = new NumVarStatMod(staticID, 16f, 10, VarStatModType.OverrideWithMods);
		dashDurMod = new NumVarStatMod(staticID, 0.4f, 10, VarStatModType.OverrideWithMods);
		jumpTime = 0.3f;
		jumpRange = 2.5f;
		jumpHeight = 1.5f;
		jumpBalance = 0.7f;
		useCalcValues = false;
	}

	public override void OnEnter()
	{
		BaseOnEnter();
		dashSpdMod.modValue = 16f;
		holdStarted = false;
		holdReleased = false;
		skillExecuted = false;
		spinAnimPlayed = false;
		jumpStarted = false;
		movementStopped = false;
		hitCounter = 0;
		maxHitCount = 3;
		hitDelay = 0.15f;
		if (IsEmpowered)
		{
			baseScale = 1.75f;
			finalScale = 3f;
		}
		else
		{
			baseScale = 1f;
			finalScale = 2.25f;
		}
		inputVector = parent.GetInputVector();
		currentQuat = Globals.GetRotationQuaternion(inputVector);
		parent.movement.moveVector = inputVector;
		parent.movement.dashVector = inputVector;
		parent.movement.dashSpeedStat.AddMod(dashSpdMod);
		parent.movement.dashDurationStat.AddMod(dashDurMod);
		parent.movement.dashTimer = dashDurMod.modValue;
		parent.ToggleEnemyFloorCollisions(status: false);
		parent.anim.PlayDirectional(OnEnterAnimStr, -1, animStartTime);
	}

	public override void Update()
	{
		if (jumpStarted)
		{
			if (!spinAnimPlayed && parentThrow.PercentComplete > 0.4f)
			{
				parent.anim.Play("SpinReverse", -1, 0f);
				spinAnimPlayed = true;
			}
			base.Update();
		}
		else if (skillExecuted)
		{
			ConcludeSkill();
		}
		else if (parent.anim.AnimPlayed(animExecTime))
		{
			ExecuteSkill();
		}
	}

	public override void FixedUpdate()
	{
		if (!movementStopped)
		{
			movementStopped = parent.movement.DashToTarget();
		}
	}

	public override void ExecuteSkill()
	{
		if (ChaosStopwatch.Check(hitStopwatchID))
		{
			StartCooldownTimer();
			hitStopwatchID = ChaosStopwatch.Begin(hitDelay);
			if (hitCounter >= 1)
			{
				hitDelay = 0.125f;
			}
			PlayAnim();
			if (hitCounter == maxHitCount - 1)
			{
				CreateFlamePunch((!IsEmpowered) ? 2 : 3);
			}
			else
			{
				CreateFlamePunch(1);
			}
			CameraController.ShakeCamera(0.25f);
			hitCounter++;
			if (hitCounter >= maxHitCount)
			{
				base.ExecuteSkill();
				InitJump();
			}
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.movement.dashSpeedStat.RemoveMod(staticID);
		parent.movement.dashDurationStat.RemoveMod(staticID);
		parent.ToggleEnemyFloorCollisions();
		CleanUpEventHandler();
	}

	private void PlayAnim()
	{
		if (hitCounter != 0)
		{
			if (hitCounter % 2 == 0)
			{
				parent.anim.PlayDirectional(parent.KickAnimStr, -1, 0.25f);
			}
			else
			{
				parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, 0.25f);
			}
		}
	}

	private void CreateFlamePunch(int givenLevel)
	{
		CleanUpEventHandler();
		currentPosition = (Vector2)parent.attackOriginTrans.position + inputVector;
		currentFP = ChaosInst<FlamePunch>(FlamePunch.Prefab, currentPosition, currentQuat);
		currentFP.SetScale((givenLevel <= 1) ? baseScale : finalScale);
		currentFP.attack.SetAttackInfo(parent.skillCategory, skillID, givenLevel);
		currentFP.attack.knockbackOverwriteVector = inputVector;
		currentFP.isFinalHit = givenLevel > 1;
		if (!movementStopped)
		{
			Attack attack = currentFP.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attack2 = currentFP.attack;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
		SoundManager.PlayWithDistAndSPR("BlazingBlitzEnd", currentPosition);
		SoundManager.PlayWithDistAndSPR("FireballCast", currentPosition, 0.9f);
	}

	private void OnTargetHit(Entity givenEntity)
	{
		if (!movementStopped && givenEntity != null && givenEntity is Enemy && givenEntity.health != null && givenEntity.health.ignoreGrab)
		{
			movementStopped = true;
			parent.movement.EndMovement();
			parent.movement.MoveToMoveVector(8f);
			CleanUpEventHandler(removeRef: false);
			jumpRange = 4f;
		}
	}

	private void CleanUpEventHandler(bool removeRef = true)
	{
		if (currentFP != null && currentFP.attack != null)
		{
			Attack attack = currentFP.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			if (removeRef)
			{
				UnityEngine.Object.Destroy(currentFP.gameObject, 0.25f);
				currentFP = null;
			}
		}
	}

	public override void OnLanding()
	{
		if (!hasLanded && !fsm.nextStateName.Contains("Hurt") && !fsm.nextStateName.Contains("Dead"))
		{
			base.OnLanding();
			parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, 0.4f);
			parent.movement.moveVector = -inputVector;
			parent.movement.MoveToMoveVector(6f);
		}
	}

	private void InitJump()
	{
		jumpStarted = true;
		startPosition = parent.transform.position;
		parent.spriteRenderer.sortingLayerName = "UI";
		SetThrowValues();
		parent.throwScript.ThrowToTargetVector(Globals.GetLinecastVector(startPosition, startPosition - inputVector * jumpRange, ChaosCollisions.layerAllWallAndObst) + inputVector * 0.5f);
		SoundManager.PlayAudioWithDistance("StandardJump", startPosition);
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 50;
		float scale = 0.25f;
		Vector3? emitPosition = startPosition + Vector2.up * 0.5f;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		hasLanded = false;
		collidersEnabled = false;
		ToggleObjects(status: false);
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ThrownItem thrownItem2 = parentThrow;
		thrownItem2.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(thrownItem2.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		landingStopwatch.SetDelay(0.1f);
	}
}

	public class UseFireBombard : SkillState
	{
		public new static string staticID = "UseFireBombard";

		private static Vector2 spawnOffset = Vector2.up * 0.25f;

		private ThrownFireball currentFB;

		private string animStr;

		private bool playAnim;

		private int atkStopwatchID;

		private bool atkStarted;

		private bool firstAtk;

		private bool posArc;

		private float spawnRange = 3f;

		private Vector2 spawnPosition;

		private Vector2 perpendVec;

		private Vector3 roteVector;

		private Vector2 landOffset;

		private int atkLv = 2;

		private int atkCountdown = 5;

		public override string OnEnterAnimStr => parent.GSlamAnimStr;

		public UseFireBombard(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			SetAnimTimes(0.15f, 0.2f, 0.3f, 0.75f, 0.85f);
		}

		public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			base.SetEmpowered(givenStatus, givenMod);
			atkLv = ((!IsEmpowered) ? 2 : 3);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			firstAtk = true;
			atkStarted = false;
			animStr = parent.GSlamAnimStr;
			playAnim = false;
			spawnRange = 3f;
			atkCountdown = 5;
		}

		public override void ExecuteSkill()
		{
			if (!atkStarted)
			{
				atkStarted = true;
				atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.1f, atkCountdown);
				perpendVec = Globals.GetPerpendicular(inputVector) * 0.75f;
				roteVector = inputVector;
				if (roteVector.y < 0f)
				{
					roteVector.y = 0f - roteVector.y;
				}
				roteVector = Globals.GetRotationVector((roteVector + Vector3.up).normalized);
			}
			switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
			{
			case StopwatchState.Ready:
				atkCountdown--;
				spawnPosition = (Vector2)parent.transform.position + inputVector;
				if (firstAtk)
				{
					firstAtk = false;
					AnnounceSkillExecuteEvent();
					CameraController.ShakeCamera();
					PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, spawnPosition, ParticleEffectOverrides.StartLifeTimeTwo);
					PoolManager.GetPoolItem<ParticleEffect>("BurnMarkMedEmitter").Emit(1, spawnPosition, ParticleEffectOverrides.StartLifeTimeTwo);
					landOffset = Vector2.zero;
				}
				else if (atkCountdown > 0)
				{
					landOffset = perpendVec * ((!posArc) ? UnityEngine.Random.value : (0f - UnityEngine.Random.value));
				}
				else
				{
					landOffset = Vector2.zero;
				}
				CreateThrownFireball(spawnPosition, spawnPosition + inputVector * spawnRange + landOffset);
				posArc = !posArc;
				spawnRange++;
				break;
			case StopwatchState.Done:
				skillExecuted = true;
				PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, spawnPosition, ParticleEffectOverrides.StartLifeTimeTwo);
				PoolManager.GetPoolItem<ParticleEffect>("BurnMarkMedEmitter").Emit(1, spawnPosition, ParticleEffectOverrides.StartLifeTimeTwo);
				break;
			}
			if (playAnim)
			{
				parent.anim.PlayDirectional(animStr, -1, 0.6f);
			}
			else
			{
				playAnim = parent.anim.AnimPlayed(0.6f);
			}
			if (!firstAtk && !skillExecuted)
			{
				CancelToDash(enableButtonHeld: true);
			}
		}

		private void CreateThrownFireball(Vector2 givenPosition, Vector2 givenLocation)
		{
			FlameBurst.CreateBurst(givenPosition, parent.skillCategory, skillID, 1, 1f, useEffects: false).attack.knockbackOverwriteVector = inputVector;
			FireExplosion.SpawnExplosion(givenPosition + UnityEngine.Random.insideUnitCircle * 0.35f, 0.75f, 0.5f, 5, 5);
			currentFB = ChaosInst<ThrownFireball>(ThrownFireball.Prefab, givenPosition + spawnOffset);
			currentFB.spriteStartPosition = Vector2.up;
			currentFB.throwHeight = spawnRange * 0.5f;
			currentFB.baseFlightTime = spawnRange * 0.0625f;
			currentFB.useCastCircle = false;
			currentFB.targetPosition = givenLocation;
			currentFB.Initialize(parent.skillCategory, skillID, atkLv, roteVector);
			currentFB.atkRadius = 1.75f;
			currentFB.atkDuration = 0.25f;
			currentFB.atkVector = inputVector;
		}
	}

