	{
		base.Start();
		if (useCastCircle)
		{
			currentCC = CastingCirclePool.Spawn("Draw", targetPosition, parentObj: gameObject, color: CastingCircle.enemyColor, disableWithParentVal: true, trackParentVal: false, useCastTimeVal: false, castTimeVal: 0f, unitSizeX: atkRadius, unitSizeY: 0f, drawTime: 0.05f);
		}
		PoolManager.GetPoolItem<FireBurst>().EmitSingle(3, transform.position, null, Vector3.up);
