		FirePillar firePillar = Globals.ChaosInst<FirePillar>(FirePillar.Prefab, null, landPosition);
		firePillar.attack.SetAttackInfo(skillCat, skillID, skillLv);
		firePillar.attack.knockbackOverwriteVector = atkVector;
		firePillar.attackRadius = atkRadius;
		firePillar.delay = 0f;
		firePillar.duration = atkDuration;
		firePillar.useCastingCircle = false;
