public class FlakFieldProjectile : Projectile
{
	private static GameObject prefab;

	public ParticleSystem trailEmitter;

	private ParticleEffect smokeEmitter;

	private FlakField curField;

	public bool isEmpowered;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/FlakFieldProjectile.prefab"));

	public override void Start()
	{
		base.Start();
		smokeEmitter = PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter");
		smokeEmitter.followTransform = transform;
		smokeEmitter.transform.position = transform.position;
		ParticleEffect particleEffect = smokeEmitter;
		float? emissionRate = 80f;
		ParticleSystemOverride startLifeTime0p = ParticleEffectOverrides.StartLifeTime0p5;
		particleEffect.Play(emissionRate, null, startLifeTime0p);
	}

	public override void ResetProjectile()
	{
		if (smokeEmitter != null)
		{
			smokeEmitter.Stop();
			smokeEmitter.followTransform = null;
			smokeEmitter = null;
		}
		if (trailEmitter != null)
		{
			trailEmitter.Stop();
		}
		CreateFlakField();
		base.ResetProjectile();
	}

	private void CreateFlakField()
	{
		curField = Globals.ChaosInst<FlakField>(FlakField.Prefab, null, (Vector2)transform.position + Vector2.down * 0.9f + moveVector * 0.35f);
		curField.attack.SetAttackInfo(attackBox.atkInfo);
		AttackInfo.SetFloorTargets(curField.attack.atkInfo.targetNames);
		curField.isEmpowered = isEmpowered;
	}
}

